import React, { useCallback } from "react";
import localStyles from "./UserList.props";
import { View, TouchableOpacity, Text, Image } from "react-native";
import { Avatar as TextAvatar } from "../Avatar/Avatar";
import { RTCView } from "react-native-webrtc";
import { useStore } from "../../store/Store";
import { SET_PINNED_USER } from "../../store/ActionType";
import { TILE_USERS_COUNT } from "../../utils/Constants";
import { ICONS } from "../../icons";
import { color } from "../../theme/color";
import { stringToColor } from "../../utils/helper";
import VideoPauseOverlay from "../Shared/VideoPauseOverlay";

const RenderAudios = React.memo(
  function renderAudios({ urls = [] }: { urls: any[] }) {
    return (
      <>
        {urls.map((item: { id: string; url: string }, index) =>
          index > 2 ? (
            <RTCView
              key={item.id}
              objectFit='cover'
              streamURL={item.url}
              style={{ height: 0, width: 0 }}
              zOrder={-1}
            />
          ) : null
        )}
      </>
    );
  },
  (prev, next) => {
    if (prev.urls.length !== next.urls.length) {
      return false;
    }
    return true;
  }
);

const UserList = React.memo(function UserList() {
  const {
    globalState: { pinnedUserId, isPortrait, dimension },
    users: allUsers,
    dispatch,
    settings: { avatarMode, isAudioOnly, enableVideoTileClick },
  } = useStore();
  const users = allUsers.filter((item) => {
    if (item.isPresenter === false) return false;
    return true;
  });
  console.log("wii", dimension.width, (dimension.width - (users.length + 1) * 5) / users.length);
  const unPinUser = useCallback(() => {
    dispatch({
      type: SET_PINNED_USER,
      payload: "",
    });
  }, []);

  const pinUser = useCallback((userId: string) => {
    dispatch({
      type: SET_PINNED_USER,
      payload: userId,
    });
  }, []);
  const renderUserList = () => {
    const userList = [...users];
    const userVideos = [];
    for (let i = 0; i < (userList.length > 2 ? 3 : userList.length); i++) {
      const item = userList[i];
      const userStats = item.stats;
      const networkColor = userStats
        ? userStats.connectionQuality < 25
          ? ICONS.NETWORK1
          : userStats.connectionQuality < 50
          ? ICONS.NETWORK2
          : userStats.connectionQuality < 75
          ? ICONS.NETWORK3
          : ICONS.NETWORK4
        : "";
      let isPinned: boolean;

      if (item.id === pinnedUserId) {
        isPinned = true;
      } else {
        isPinned = false;
      }

      if (
        item.videoTrack &&
        !item.isVideoMuted &&
        (item.status !== "inactive" || i === 0)
        // &&
        // (resolutions[item.id]
        //   ? Object.values(resolutions[item.id])[0].width != 0 &&
        //     Object.values(resolutions[item.id])[0].height != 0
        //   : true)
      ) {
        userVideos.push(
          <TouchableOpacity
            activeOpacity={1}
            touchSoundDisabled
            onPress={() => {
              if (!enableVideoTileClick) return;
              if (isPinned) {
                unPinUser();
              } else {
                pinUser(item.id);
              }
            }}
            key={item.id}
            // rippleColor="rgba(0, 0, 0, .20)"
            style={localStyles.user_list_main_touchable}
          >
            <View
              style={{
                // [isPortrait ? "width" : "height"]:
                //   (isPortrait ? flex1?.width : flex1?.height) * 0.25 || 100,
                [isPortrait ? "width" : "height"]:
                  (dimension[isPortrait ? "width" : "height"] - (TILE_USERS_COUNT + 1) * 10) /
                  TILE_USERS_COUNT,
                aspectRatio: 1,
                alignItems: "center",
                justifyContent: "center",
                flexDirection: "column",
                borderRadius: 8,
                overflow: "hidden",
                [isPortrait ? "marginHorizontal" : "marginVertical"]: 4,
                backgroundColor: color.blackLightX,
                marginBottom: 5,
              }}
            >
              <Text numberOfLines={1} ellipsizeMode='tail' style={localStyles.user_list_user_name}>
                {item.name || ""}
              </Text>
              <View style={localStyles.user_list_icon_container}>
                {item.isAudioMuted ? (
                  <View style={localStyles.lt_small_button}>
                    <Image style={localStyles.user_item_icons} source={ICONS.AUDIO_MUTE} />
                  </View>
                ) : null}

                {item.isVideoMuted && !isAudioOnly ? (
                  <View style={localStyles.lt_small_button}>
                    <Image style={localStyles.user_item_icons} source={ICONS.VIDEO_MUTE} />
                  </View>
                ) : null}
              </View>
              {isPinned ? (
                <View
                  style={{
                    ...localStyles.lt_small_button,
                    position: "absolute",
                    top: 5,
                    right: 5,
                    elevation: 5,
                  }}
                >
                  <Image style={localStyles.user_item_icons} source={ICONS.PIN} />
                </View>
              ) : null}
              <RTCView
                key={item.id}
                objectFit='cover'
                streamURL={item.videoTrack?.getOriginalStream().toURL()}
                style={[localStyles.full_height_width, { borderRadius: 5 }]}
                zOrder={1}
                mirror={
                  users[0].id === item.id
                    ? item.videoTrack._facingMode === "environment"
                      ? false
                      : true
                    : false
                }
              />

              {item.isMutedWhenInBackground && <VideoPauseOverlay />}
              <View style={localStyles.user_list_network_container}>
                {/* <NetworkIcon fill={networkColor}/> */}
                {networkColor ? (
                  <Image
                    resizeMode='contain'
                    source={networkColor}
                    style={[localStyles.user_list_network_icon]}
                  />
                ) : null}
              </View>
            </View>
            {/* <Text>
                {resolutions[0] &&
                  Object.values(resolutions[item.id])[0].width +
                    " , " +
                    Object.values(resolutions[item.id])[0].height}
              </Text> */}
          </TouchableOpacity>
        );
      } else {
        userVideos.push(
          <TouchableOpacity
            activeOpacity={1}
            touchSoundDisabled
            onPress={() => {
              if (!enableVideoTileClick) return;
              if (isPinned) {
                unPinUser();
              } else {
                pinUser(item.id);
              }
            }}
            key={item.id}
            // rippleColor="rgba(0, 0, 0, .20)"
            style={localStyles.user_list_main_touchable}
          >
            <View
              style={{
                // [isPortrait ? "width" : "height"]:
                //   (isPortrait ? flex1?.width : flex1?.height) * 0.25 || 100,
                [isPortrait ? "width" : "height"]:
                  (dimension[isPortrait ? "width" : "height"] - (TILE_USERS_COUNT + 1) * 10) /
                  TILE_USERS_COUNT,
                aspectRatio: 1,
                alignItems: "center",
                justifyContent: "center",
                flexDirection: "column",
                borderRadius: 8,
                overflow: "hidden",
                [isPortrait ? "marginHorizontal" : "marginVertical"]: 4,
                backgroundColor: color.blackLight,
                marginBottom: 5,
              }}
            >
              <View style={localStyles.user_list_icon_container}>
                {item.isAudioMuted ? (
                  <View style={localStyles.lt_small_button}>
                    <Image style={localStyles.user_item_icons} source={ICONS.AUDIO_MUTE} />
                  </View>
                ) : null}
                {item.isVideoMuted && !isAudioOnly ? (
                  <View style={localStyles.lt_small_button}>
                    <Image style={localStyles.user_item_icons} source={ICONS.VIDEO_MUTE} />
                  </View>
                ) : null}
              </View>
              {isPinned ? (
                <View
                  style={{
                    ...localStyles.lt_small_button,
                    position: "absolute",
                    top: 5,
                    right: 5,
                    elevation: 5,
                    zIndex: 5,
                  }}
                >
                  <Image style={localStyles.user_item_icons} source={ICONS.PIN} />
                </View>
              ) : null}
              <TextAvatar
                backgroundColor={stringToColor(item?.name)}
                textColor={"#FFF"}
                size={30}
                avatar={item.avatar}
              >
                {item.name || ""}
              </TextAvatar>
              <View
                style={
                  avatarMode == "fullscreen"
                    ? {
                        position: "absolute",
                        top: 5,
                        left: 5,
                        justifyContent: "center",
                        alignItems: "center",
                      }
                    : {
                        alignItems: "center",
                      }
                }
              >
                <Text
                  numberOfLines={1}
                  ellipsizeMode={"tail"}
                  style={localStyles.user_list_avatar_name}
                >
                  {item.name || ""}
                </Text>
                {/* <AudioLevelIndicator track={item.audioTrack} /> */}
              </View>
              <RTCView
                key={item.id}
                objectFit='cover'
                streamURL={item.audioTrack?.getOriginalStream().toURL()}
                // TODO: Below line commented
                // style={localStyles.zero_height_width}
                zOrder={-1}
              />
              {item.isMutedWhenInBackground && <VideoPauseOverlay />}
            </View>
          </TouchableOpacity>
        );
      }
    }

    return <>{userVideos}</>;
  };

  return (
    <View
      style={[
        localStyles.main_container,
        isPortrait ? { paddingVertical: 5 } : { paddingRight: 10, paddingVertical: 5 },
      ]}
    >
      <View
        style={
          isPortrait
            ? {
                width: "100%",
                flexDirection: "row",
                justifyContent: "space-between",
                // marginBottom: 5,
              }
            : {
                width: "100%",
                height: "100%",
                justifyContent: "space-between",
                // marginRight: 5,
              }
        }
      >
        <View
          style={{
            flexDirection: isPortrait ? "row" : "column",
            flex: 1,
            // justifyContent: "center",
            marginHorizontal: isPortrait ? 8 : 0,
          }}
        >
          {users?.length >= 1 ? renderUserList() : null}
          {users?.length >= 3 && (
            <RenderAudios
              urls={users.map((item) => ({
                id: item.id,
                url: item.audioTrack?.getOriginalStream().toURL(),
              }))}
            />
          )}
        </View>

        {/* {users.length > 1 ? (
            <TouchableOpacity touchSoundDisabled onPress={toggleUserList}>
              <View
                style={{
                  ...(isPortrait
                    ? {
                      width: "100%",
                      height: "100%",
                    }
                    : {
                      // width: flex1?.width * 0.18,
                      marginHorizontal: 5,
                      // height: flex1?.height * 0.18,
                      width: "100%",
                      height: "100%",
                    }),
                  alignItems: "center",
                  justifyContent: "center",
                  flexDirection: isPortrait ? "column" : "row",
                  borderRadius: 5,
                  marginHorizontal: 5,
                  backgroundColor: "#000",
                }}
              >
                <Text
                  style={{
                    fontSize: 18,
                    color: "#fff",
                    padding: 5,
                  }}
                >
                  {users.length.toString()}
                </Text>
                <Text
                  adjustsFontSizeToFit
                  numberOfLines={1}
                  style={{
                    fontSize: 18,
                    color: "#fff",
                    padding: 5,
                  }}
                >
                  users
                </Text>
              </View>
            </TouchableOpacity>
          ) : null} */}
      </View>
    </View>
  );
});

export default UserList;
