import { ON_SWITCHED_TO_VIDEO_CALL, TOGGLE_VIDEO_FIT } from "./ActionType";
import { ICallSettingAction, ICallSettings } from "./CallSettings.types";

export const callSettingReducer = (state: ICallSettings, { type, payload }: ICallSettingAction) => {
  switch (type) {
    case ON_SWITCHED_TO_VIDEO_CALL:
      return {
        ...state,
        isAudioOnly: false,
      };
    case TOGGLE_VIDEO_FIT:
      return {
        ...state,
        videoSettings: { ...state.videoSettings, videoFit: payload },
      };
    default:
      return { ...state };
  }
};
