import React, { createContext, useContext, useReducer, useRef, useState } from "react";
import { callSettingReducer } from "./CallSettingsReducer";
import { IContext } from "./Context.types";
import { initialGlobalState, reducer } from "./GlobalReducer";
import { userReducer } from "./UserReducer";
// TODO: Need to provide initial value
export const Context = createContext<IContext>(null);
export const useStore = () => useContext(Context);

interface PropsInterface {
  children: any;
  initialState: any;
  reducer: typeof reducer;
}

// TODO: Why we need to pass reducer as props ??
export const ContextProvider = ({ children, initialState, reducer }: PropsInterface) => {
  const [settings, setSettings] = useReducer(callSettingReducer, initialState);
  const [globalState, dispatch] = useReducer(reducer, initialGlobalState);
  const globalRef = useRef({});
  const usersRef = useRef([]);
  const timerRef = useRef(null);
  const [users, setUsers] = useReducer(userReducer, []);
  const [connection, setConnection] = useState(null);
  const [room, setRoom] = useState(null);
  const jitsiManager = useRef();
  const nativeManager = useRef();

  const setUserMiddleWare = (users, imp = false) => {
    if (imp) {
      setUsers(users);
      return;
    }
    if (timerRef.current) {
      clearTimeout(timerRef.current);
    }
    timerRef.current = setTimeout(() => {
      setUsers(users);
    }, 500);
  };

  return (
    <Context.Provider
      value={{
        globalRef,
        settings,
        setSettings,
        globalState,
        connection,
        setConnection,
        room,
        setRoom,
        dispatch,
        users,
        setUsers: setUserMiddleWare,
        jitsiManager,
        nativeManager,
        usersRef,
      }}
    >
      {children}
    </Context.Provider>
  );
};
