import React from "react";
import { TouchableOpacity, Image, View, Text } from "react-native";
import { useStore } from "../../store/Store";
import { ICONS } from "../../icons";
import { TOGGLE_PARTICIPANTS_MODEL } from "../../store/ActionType";
import { sharedObject } from "../../utils/common";

interface IUserListButton {
  userLength: number;
  onButtonPress: () => void;
}

export function UserListButton({ userLength, onButtonPress }: IUserListButton) {
  const {
    dispatch,
    globalState: { isParticipantsModelVisible },
  } = useStore();

  const onPress = () => {
    onButtonPress();
    dispatch({
      type: TOGGLE_PARTICIPANTS_MODEL,
      payload: !isParticipantsModelVisible,
    });
  };
  return (
    <>
      <TouchableOpacity
        testID='cc-user-list'
        disabled={sharedObject.isPresenter === false}
        touchSoundDisabled
        onPress={onPress}
        style={{ paddingHorizontal: 2 }}
      >
        <Image style={{ width: 25, height: 22 }} source={ICONS.PEOPLE} />
        <View
          style={{
            backgroundColor: "#1E79E7",
            height: 15,
            minWidth: 15,
            borderRadius: 15,
            position: "absolute",
            right: -5,
            top: -10,
            justifyContent: "center",
            alignItems: "center",
          }}
        >
          <Text style={{ color: "#fff", fontSize: 10 }}>{userLength}</Text>
        </View>
      </TouchableOpacity>
    </>
  );
}
