import React from "react";
import { TouchableOpacity, View } from "react-native";
import { useStore } from "../../store/Store";
import style from "./Buttons.styles";
import Logger from "../../utils/Logger";
import { RECORDING_BUTTON_SIZE } from "../../utils/Constants";
import { color } from "../../theme/color";
const TAG = "RecordingButton";
export function RecordingButton() {
  const { globalState, jitsiManager } = useStore();

  const onButtonPress = () => {
    try {
      Logger.d(TAG, "[onButtonPress]");
      if (!globalState.isRecording) {
        jitsiManager.current.startRecording();
      } else {
        jitsiManager.current.stopRecording();
      }
    } catch (error) {
      Logger.d(TAG, "[onButtonPress]", error);
    }
  };
  return (
    <TouchableOpacity
      testID='cc-rec'
      style={style.buttonContainer}
      touchSoundDisabled
      onPress={onButtonPress}
    >
      <View
        style={{
          width: RECORDING_BUTTON_SIZE,
          height: RECORDING_BUTTON_SIZE,
          backgroundColor: color.palette.red,
          borderRadius: globalState.isRecording ? 0 : RECORDING_BUTTON_SIZE,
        }}
      />
    </TouchableOpacity>
  );
}
