import React from "react";
import { Image } from "react-native";
import { ICONS } from "../../icons";

const NetworkComp = ({ connectionQuality }: { connectionQuality: number }) => {
  const ActiveIcon =
    connectionQuality < 25
      ? ICONS.NETWORK1
      : connectionQuality < 50
      ? ICONS.NETWORK2
      : connectionQuality < 75
      ? ICONS.NETWORK3
      : ICONS.NETWORK4;
  return <Image resizeMode='contain' source={ActiveIcon} style={[{ height: 20, width: 20 }]} />;
};

export default React.memo(NetworkComp, (prev, next) => {
  return Math.ceil(prev.connectionQuality / 25) === Math.ceil(next.connectionQuality / 25);
});
