import React from "react";
import { TouchableOpacity, Image } from "react-native";
import { ICONS } from "../../icons";
import { useStore } from "../../store/Store";
import Logger from "../../utils/Logger";
import style from "./Buttons.styles";
const TAG = "SwitchCameraButton";
export function SwitchCameraButton() {
  const { jitsiManager } = useStore();

  const onButtonPress = () => {
    try {
      Logger.d(TAG, "[onButtonPress]");
      Logger.d(TAG, "[onButtonPress]");
      jitsiManager.current.flipCamera();
    } catch (error) {
      Logger.d(TAG, "[onButtonPress]", error);
    }
  };
  return (
    <TouchableOpacity
      testID='cc-switch-camera'
      style={style.buttonContainer}
      touchSoundDisabled
      onPress={onButtonPress}
    >
      <Image style={style.buttonIcon} source={ICONS.SWITCH_CAMERA} />
    </TouchableOpacity>
  );
}
