import React, { useCallback, useState } from "react";
import localStyles from "./MainVideo.styles";
import {
  View,
  TouchableOpacity,
  Image,
  Text,
  Platform,
  UIManager,
  LayoutAnimation,
  ActivityIndicator,
} from "react-native";
import { Avatar as TextAvatar } from "../Avatar/Avatar";
import { RTCView } from "react-native-webrtc";
import { useStore } from "../../store/Store";
import { SET_PINNED_USER, TOGGLE_VIDEO_FIT } from "../../store/ActionType";
import { ICONS } from "../../icons";
import { color } from "../../theme/color";
import { ZoomableView } from "../../lib";
import { stringToColor } from "../../utils/helper";
import { UserListButton } from "../MainVideoItems/UserListButton";
import { FullScreenButton } from "../MainVideoItems/FullScreenButton";
import { ZoomButton } from "../MainVideoItems/ZoomButton";
import { sharedObject } from "../../utils/common";
import VideoPauseOverlay from "../Shared/VideoPauseOverlay";

if (Platform.OS === "android") {
  if (UIManager.setLayoutAnimationEnabledExperimental) {
    UIManager.setLayoutAnimationEnabledExperimental(true);
  }
}

const RenderUserStats = ({
  isMenuVisible,
  mainVideoSpeaker,
  setIsMenuVisible,
  pinUser,
  unPinUser,
  pinnedUserId,
  jitsiManager,
  localUserId,
  isAudioOnly,
  networkColor,
  nameLabel,
}: {
  isMenuVisible: any;
  mainVideoSpeaker: any;
  setIsMenuVisible: any;
  pinUser: any;
  unPinUser: any;
  pinnedUserId: any;
  jitsiManager: any;
  localUserId: any;
  isAudioOnly: any;
  networkColor: any;
  nameLabel: any;
}) => {
  let menuPosition: any = { top: -45, right: 5 };
  if (nameLabel)
    switch (nameLabel.position) {
      case "top-right":
        menuPosition = { top: 45, right: 5 };
        break;
      case "bottom-right":
        menuPosition = { bottom: 40, right: 5 };
        break;
      case "top-left":
        menuPosition = { top: 45, right: 5 };
        break;
      case "bottom-left":
        menuPosition = { bottom: 40, right: 5 };
        break;
      default:
        break;
    }
  return (
    <View style={[localStyles.user_stats_container]}>
      {isMenuVisible && (
        <View style={[localStyles.user_stats_menu, menuPosition]}>
          <TouchableOpacity
            onPress={() => {
              if (mainVideoSpeaker.id === pinnedUserId) {
                unPinUser();
              } else {
                pinUser(mainVideoSpeaker.id);
              }
              setIsMenuVisible(false);
            }}
            style={localStyles.user_stats_menu_list}
          >
            <Image style={localStyles.user_stats_menu_icon} source={ICONS.PIN} />
            <Text style={localStyles.user_stats_menu_text}>
              {mainVideoSpeaker.id === pinnedUserId ? "Unpin" : "Pin"}
            </Text>
          </TouchableOpacity>
          {mainVideoSpeaker.isAudioMuted || mainVideoSpeaker.id === localUserId ? null : (
            <TouchableOpacity
              onPress={() => {
                jitsiManager.current.muteParticipant(mainVideoSpeaker);
                setIsMenuVisible(false);
              }}
              style={localStyles.user_stats_menu_list}
            >
              <Image style={localStyles.user_detail_icons} source={ICONS.AUDIO_MUTE} />
              <Text style={localStyles.user_stats_menu_text}>Mute</Text>
            </TouchableOpacity>
          )}
        </View>
      )}
      <View style={[localStyles.user_details_container, { backgroundColor: nameLabel.color }]}>
        <View style={localStyles.user_details_container_two}>
          <Image
            style={[
              localStyles.user_detail_icons,
              { tintColor: mainVideoSpeaker.isAudioMuted ? color.red : color.green },
            ]}
            source={mainVideoSpeaker.isAudioMuted ? ICONS.AUDIO_MUTE : ICONS.AUDIO_UNMUTE}
          />
          {isAudioOnly ? null : (
            <Image
              style={[
                localStyles.user_detail_icons,
                { tintColor: mainVideoSpeaker.isVideoMuted ? color.red : color.green },
              ]}
              source={mainVideoSpeaker.isVideoMuted ? ICONS.VIDEO_MUTE : ICONS.VIDEO_UNMUTE}
            />
          )}
          <Text
            numberOfLines={1}
            ellipsizeMode={"tail"}
            style={{ ...localStyles.main_video_name, padding: 10, maxWidth: 100 }}
          >
            {mainVideoSpeaker.name}
          </Text>
        </View>
        <View style={localStyles.user_details_container_two}>
          {networkColor ? (
            <Image
              resizeMode='contain'
              source={networkColor}
              style={localStyles.user_detail_icons}
            />
          ) : null}
          <TouchableOpacity
            onPress={() => {
              console.log("pressed");
              setIsMenuVisible((prev) => !prev);
            }}
          >
            <Image resizeMode='contain' source={ICONS.MENU} style={localStyles.user_detail_icons} />
          </TouchableOpacity>
        </View>
      </View>
    </View>
  );
};

const RenderMainVideo = React.memo(
  ({
    cameraFlipped,
    videoFit,
    isMenuVisible,
    setIsMenuVisible,
    pinUser,
    unPinUser,
    pinnedUserId,
    jitsiManager,
    users,
    isAudioOnly,
    networkColor,
    dominantSpeakerId,
    mainVideoSpeaker,
  }: {
    cameraFlipped: boolean;
    videoFit: any;
    isMenuVisible: any;
    setIsMenuVisible: any;
    pinUser: any;
    unPinUser: any;
    pinnedUserId: any;
    jitsiManager: any;
    users: any;
    isAudioOnly: any;
    networkColor: any;
    dominantSpeakerId: any;
    mainVideoSpeaker: any;
  }) => {
    if (mainVideoSpeaker) {
      const dominantVideoTrack = mainVideoSpeaker.videoTrack;
      const userStats = mainVideoSpeaker.stats;
      networkColor = userStats
        ? userStats.connectionQuality < 25
          ? ICONS.NETWORK1
          : userStats.connectionQuality < 50
          ? ICONS.NETWORK2
          : userStats.connectionQuality < 75
          ? ICONS.NETWORK3
          : ICONS.NETWORK4
        : "";

      //   const isTrackOfTypeScreenSharing = isScreenSharingTrack(
      //     dominantVideoTrack
      //   );
      try {
        if (mainVideoSpeaker.id) {
          // const ids = [mainVideoSpeaker.id];
          // room.selectParticipants(ids);
        }
      } catch (err) {
        // Logger.log(TAG, "selectParticipants ids error : ", err);
      }

      if (mainVideoSpeaker && (mainVideoSpeaker.isVideoMuted || !mainVideoSpeaker.videoTrack)) {
        return (
          <TouchableOpacity
            activeOpacity={1}
            onPress={() => {
              if (isMenuVisible) setIsMenuVisible(false);
            }}
            style={[
              localStyles.main_video_video_track_view,
              {
                justifyContent: "center",
                alignItems: "center",
              },
            ]}
          >
            <TextAvatar
              backgroundColor={stringToColor(mainVideoSpeaker?.name)}
              textColor={"#FFF"}
              size={160}
              avatar={mainVideoSpeaker.avatar}
            >
              {mainVideoSpeaker.name}
            </TextAvatar>
            <RTCView
              key={mainVideoSpeaker.id}
              objectFit='cover'
              streamURL={mainVideoSpeaker.audioTrack?.getOriginalStream().toURL()}
              style={localStyles.zero_height_width}
              zOrder={-10}
            />
            {mainVideoSpeaker.isMutedWhenInBackground && <VideoPauseOverlay />}
          </TouchableOpacity>
        );
      }

      // Logger.log(TAG,"RenderMainVideo with dominant video track.... ",dominantVideoTrack)
      if (dominantVideoTrack) {
        const sourceName = dominantVideoTrack.getSourceName?.();
        jitsiManager?.current?.setConstraints(
          sourceName,
          dominantVideoTrack.getVideoType() === "desktop" ? 1080 : 720
        );
        return (
          <View style={localStyles.main_video_video_track_view}>
            <ZoomableView
              onPress={() => {
                if (isMenuVisible) setIsMenuVisible(false);
              }}
            >
              {dominantVideoTrack?.getOriginalStream()?.toURL() ? (
                <>
                  <RTCView
                    key={dominantVideoTrack.getOriginalStream().toURL()}
                    objectFit={videoFit === "cover" ? "cover" : "contain"}
                    streamURL={dominantVideoTrack.getOriginalStream().toURL()}
                    style={localStyles.full_height_width}
                    zOrder={-10}
                    mirror={
                      users[0].id === mainVideoSpeaker.id
                        ? dominantVideoTrack?._facingMode === "environment"
                          ? false
                          : true
                        : false
                    }
                  />
                  {mainVideoSpeaker.isMutedWhenInBackground && <VideoPauseOverlay />}
                </>
              ) : null}
            </ZoomableView>
          </View>
        );
      }
    }
    return null;
  },
  (prev, next) => {
    if (
      prev.isMenuVisible !== next.isMenuVisible ||
      prev.setIsMenuVisible !== next.setIsMenuVisible ||
      prev.pinnedUserId !== next.pinnedUserId ||
      prev.isAudioOnly !== next.isAudioOnly ||
      prev.dominantSpeakerId !== next.dominantSpeakerId ||
      prev.mainVideoSpeaker.isAudioMuted !== next.mainVideoSpeaker.isAudioMuted ||
      prev.mainVideoSpeaker.isVideoMuted !== next.mainVideoSpeaker.isVideoMuted ||
      prev.mainVideoSpeaker.isVideoMuted !== next.mainVideoSpeaker.isVideoMuted ||
      prev.mainVideoSpeaker.isMutedWhenInBackground !==
        next.mainVideoSpeaker.isMutedWhenInBackground ||
      prev.videoFit !== next.videoFit ||
      prev.cameraFlipped !== next.cameraFlipped
    ) {
      return false;
    }
    return true;
  }
);

const MainVideo = ({ setFullScreen = () => null }: any) => {
  const {
    globalState: { dominantSpeakerId, pinnedUserId, cameraFlipped },
    users,
    dispatch,
    jitsiManager,
    settings: {
      isAudioOnly,
      videoSettings: { videoFit, nameLabel, fullScreenButton, userListButton, zoomButton },
    },
    setSettings,
  } = useStore();

  const [isMenuVisible, setIsMenuVisible] = useState(false);
  let networkColor;
  const unPinUser = useCallback(() => {
    dispatch({
      type: SET_PINNED_USER,
      payload: "",
    });
  }, []);

  const pinUser = useCallback((userId: string) => {
    dispatch({
      type: SET_PINNED_USER,
      payload: userId,
    });
  }, []);

  const localUser = users[0];
  let mainVideoSpeaker: any;
  const dominantUser = users.find((user) => user.id === dominantSpeakerId) || localUser;
  const pinnedUser = users.find((user) => user.id === pinnedUserId);
  const presentersCount = users.reduce((a, b) => a + (b.isPresenter !== false ? 1 : 0), 0);
  const userListButtonFun = () => (
    <UserListButton
      userLength={users.length}
      onButtonPress={() => {
        LayoutAnimation.configureNext(LayoutAnimation.Presets.linear);
        LayoutAnimation.configureNext({
          duration: 100,
          create: { type: "linear", property: "scaleY" },
          update: { type: "linear", property: "scaleY" },
          delete: { type: "linear", property: "opacity" },
        });
      }}
    />
  );
  const fullScreenButtonFun = () => (
    <FullScreenButton
      fullScreen={false}
      onButtonPress={() => {
        LayoutAnimation.configureNext(LayoutAnimation.Presets.linear);
        LayoutAnimation.configureNext({
          duration: 100,
          create: { type: "linear", property: "scaleY" },
          update: { type: "linear", property: "scaleY" },
          delete: { type: "linear", property: "opacity" },
        });
        setFullScreen((prev) => !prev);
      }}
    />
  );
  const zoomButtonFun = () => (
    <ZoomButton
      onButtonPress={() => {
        console.log("zoomButtonFun>>>");

        LayoutAnimation.configureNext(LayoutAnimation.Presets.linear);
        LayoutAnimation.configureNext({
          duration: 200,
          create: { type: "linear", property: "scaleY" },
          update: { type: "linear", property: "scaleY" },
          delete: { type: "linear", property: "opacity" },
        });

        setSettings({
          type: TOGGLE_VIDEO_FIT,
          payload: videoFit === "cover" ? "contain" : "cover",
        });
      }}
      videoFit={videoFit}
    />
  );
  mainVideoSpeaker = dominantUser;
  const renderUserStats = () => (
    <RenderUserStats
      isMenuVisible={isMenuVisible}
      mainVideoSpeaker={mainVideoSpeaker}
      setIsMenuVisible={setIsMenuVisible}
      pinUser={pinUser}
      unPinUser={unPinUser}
      pinnedUserId={pinnedUserId}
      jitsiManager={jitsiManager}
      localUserId={users[0]?.id}
      isAudioOnly={isAudioOnly}
      networkColor={networkColor}
      nameLabel={nameLabel}
    />
  );

  if (pinnedUser) {
    mainVideoSpeaker = pinnedUser;
  }
  if (sharedObject.isPresenter === false && mainVideoSpeaker.isPresenter === false) {
    for (let i = 0; i < users.length; i++) {
      if (users[i].isPresenter !== false) {
        mainVideoSpeaker = users[i];
        break;
      }
    }
  }
  if (presentersCount < 1) {
    return (
      <View
        style={{
          flex: 1,
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <ActivityIndicator size={"small"} color='#fff' />
        <Text style={{ marginLeft: 10, color: "#fff" }}>Waiting for presenter...</Text>
      </View>
    );
  }
  return (
    <>
      <View style={localStyles.main_video_container}>
        <RenderMainVideo
          cameraFlipped={cameraFlipped}
          videoFit={videoFit}
          isMenuVisible={isMenuVisible}
          setIsMenuVisible={setIsMenuVisible}
          pinUser={pinUser}
          unPinUser={unPinUser}
          pinnedUserId={pinnedUserId}
          jitsiManager={jitsiManager}
          users={users}
          isAudioOnly={isAudioOnly}
          networkColor={networkColor}
          dominantSpeakerId={dominantSpeakerId}
          mainVideoSpeaker={{ ...mainVideoSpeaker }}
        />
        <View style={[localStyles.videoItemContainer, { top: 0 }]}>
          <View style={{ flex: 1 }}>
            <View
              style={[
                localStyles.videoInnerContainer,
                {
                  top: 0,
                  left: 0,
                },
              ]}
            >
              {nameLabel?.visibility && nameLabel.position === "top-left" && renderUserStats()}
              {userListButton?.visibility &&
                userListButton.position === "top-left" &&
                userListButtonFun()}
              {zoomButton?.visibility && zoomButton.position === "top-left" && zoomButtonFun()}
              {fullScreenButton?.visibility &&
                fullScreenButton.position === "top-left" &&
                fullScreenButtonFun()}
            </View>

            <View
              style={[
                localStyles.videoInnerContainer,
                {
                  top: 0,
                  right: 0,
                },
              ]}
            >
              {nameLabel?.visibility && nameLabel.position === "top-right" && renderUserStats()}
              {userListButton?.visibility &&
                userListButton.position === "top-right" &&
                userListButtonFun()}
              {zoomButton?.visibility && zoomButton.position === "top-right" && zoomButtonFun()}
              {fullScreenButton?.visibility &&
                fullScreenButton.position === "top-right" &&
                fullScreenButtonFun()}
              {pinnedUserId ? (
                <TouchableOpacity
                  touchSoundDisabled
                  style={localStyles.pin_icon_container}
                  onPress={() => unPinUser()}
                >
                  <Image style={localStyles.pin_icon} source={ICONS.PIN} />
                </TouchableOpacity>
              ) : null}
            </View>
          </View>
        </View>
        <View style={[localStyles.videoItemContainer, { bottom: 0 }]}>
          <View style={{ flex: 1 }}>
            <View
              style={[
                localStyles.videoInnerContainer,
                {
                  bottom: 0,
                  left: 0,
                },
              ]}
            >
              {nameLabel?.visibility && nameLabel.position === "bottom-left" && renderUserStats()}
              {userListButton?.visibility &&
                userListButton.position === "bottom-left" &&
                userListButtonFun()}
              {zoomButton?.visibility && zoomButton.position === "bottom-left" && zoomButtonFun()}
              {fullScreenButton?.visibility &&
                fullScreenButton.position === "bottom-left" &&
                fullScreenButtonFun()}
            </View>
            <View
              style={[
                localStyles.videoInnerContainer,
                {
                  bottom: 0,
                  right: 0,
                },
              ]}
            >
              {nameLabel?.visibility && nameLabel.position === "bottom-right" && renderUserStats()}
              {userListButton?.visibility &&
                userListButton.position === "bottom-right" &&
                userListButtonFun()}
              {zoomButton?.visibility && zoomButton.position === "bottom-right" && zoomButtonFun()}
              {fullScreenButton?.visibility &&
                fullScreenButton.position === "bottom-right" &&
                fullScreenButtonFun()}
            </View>
          </View>
        </View>
      </View>
    </>
  );
};

export default MainVideo;
