import React, { Component } from "react";
import { Image, StyleSheet } from "react-native";
import { IContext } from "../../store/Context.types";
import { Context } from "../../store/Store";
import { color } from "../../theme/color";
import { capitalizeFirstLetter } from "../../utils";
import { AvatarProps } from "./Avatar.props";
import { TextAvatar } from "./TextAvatar";
// import initials from 'initials'

export class Avatar extends Component<AvatarProps> {
  // style: StyleProp<{[key: string]: ViewStyle | TextStyle | ImageStyle}> = {};
  static contextType?: React.Context<IContext> = Context;
  constructor(props: AvatarProps) {
    super(props);

    if (typeof props.size !== "number") throw new Error("Size must be an integer");
    // this.style = getLocalStyles({size: props.size, backgroundColor: props.backgroundColor, avatar: "test"})
  }

  render() {
    const {
      children,
      size = 60,
      backgroundColor = color.blackLightXX,
      textColor = color.palette.white,
      style,
      avatar,
    } = this.props;
    const type = (this.context as IContext).settings?.avatarMode;
    if (typeof children !== "string") {
      throw new Error("Children must be only a string \n Ex: Technology");
    }

    const abbr = capitalizeFirstLetter(children);

    const containerStyle = {
      width: size,
      height: size,
      borderRadius: size / 2,
      ...(!avatar ? { backgroundColor: backgroundColor } : {}),
    };
    const squareContainerStyle = {
      width: size,
      height: size,
      borderRadius: (size * 6) / 100,
      ...(!avatar ? { backgroundColor: backgroundColor } : {}),
    };
    const fullScreenContainerStyle = {
      width: "100%",
      height: "100%",
      borderRadius: 8,
      ...(!avatar ? { backgroundColor: backgroundColor } : {}),
    } as const;

    const textStyles = {
      color: textColor,
      fontSize: size / 3.14,
    };

    if (type?.toLowerCase() == "square") {
      if (avatar) {
        return (
          <Image
            source={{
              uri: avatar,
            }}
            style={[style, localStyles.center, squareContainerStyle]}
          />
        );
      }
      return (
        <TextAvatar
          containerStyle={[style, localStyles.center, containerStyle, { borderRadius: 0 }]}
          textStyles={textStyles}
          text={abbr}
        />
      );
    } else if (type?.toLowerCase() == "fullscreen") {
      if (avatar) {
        return (
          <Image
            resizeMode='cover'
            source={{
              uri: avatar,
            }}
            style={[style, localStyles.center, fullScreenContainerStyle]}
          />
        );
      }
      containerStyle.borderRadius = size / 2;
      return (
        <TextAvatar
          containerStyle={[style, localStyles.center, containerStyle]}
          textStyles={textStyles}
          text={abbr}
        />
      );
    } else {
      // Default case is circle
      if (avatar) {
        return <Image source={{ uri: avatar }} style={[style, containerStyle]} />;
      }
      return (
        <TextAvatar
          containerStyle={[style, localStyles.center, containerStyle]}
          textStyles={textStyles}
          text={abbr}
        />
      );
    }
  }
}

const localStyles = StyleSheet.create({
  center: {
    alignItems: "center",
    justifyContent: "center",
  },
  text: {
    fontWeight: "bold",
    letterSpacing: 1,
  },
});

