import React from "react";
import { TouchableOpacity, Image } from "react-native";
import { useStore } from "../../store/Store";
import style from "./Buttons.styles";
import Logger from "../../utils/Logger";
import { AUDIO_MODE_TYPE } from "../../utils/Constants";
import { ICONS } from "../../icons";
import { TOGGLE_AUDIO_MODE_MODEL } from "../../store/ActionType";
const TAG = "AudioModeButton";
// TODO: need to work on audio mode
export function AudioModeButton() {
  const { globalState, dispatch } = useStore();
  const onButtonPress = () => {
    try {
      dispatch({
        type: TOGGLE_AUDIO_MODE_MODEL,
        payload: true,
      });
      Logger.d(TAG, "[onButtonPress]");
    } catch (error) {
      Logger.d(TAG, "[onButtonPress]", error);
    }
  };
  const getIcon = () => {
    switch (globalState.selectedAudioMode) {
      case AUDIO_MODE_TYPE.SPEAKER:
        return ICONS.AUDIO_MODE_SPEAKER;
      case AUDIO_MODE_TYPE.BLUETOOTH:
        return ICONS.AUDIO_MODE_BLUETOOTH;
      case AUDIO_MODE_TYPE.EARPIECE:
        return ICONS.AUDIO_MODE_EARPIECE;
      case AUDIO_MODE_TYPE.HEADPHONES:
        return ICONS.AUDIO_MODE_HEADPHONE;
      default:
        return ICONS.AUDIO_MODE_SPEAKER;
    }
  };
  return (
    <TouchableOpacity testID='cc-audio-mode' onPress={onButtonPress} style={style.buttonContainer}>
      <Image style={style.buttonIcon} source={getIcon()} />
    </TouchableOpacity>
  );
}
