import React from "react";
import {
  StyleSheet,
  View,
  Text,
  Animated,
  TouchableOpacity,
  StyleProp,
  ViewStyle,
  TextStyle,
  ColorValue,
} from "react-native";
import { IAudioMode } from "../store/GlobalState.types";
import { AUDIO_MODE_TYPE } from "./Constants";

interface PropsInterface {
  style: StyleProp<ViewStyle>;
  boxStyle: StyleProp<ViewStyle>;
  textStyle: StyleProp<TextStyle>;
  initial: number;
  circleSize: number;
  duration: number;
  data: IAudioMode[];
  animationTypes: any[];
  selectedBtn: (item: IAudioMode) => void;
  activeColor: ColorValue;
  deactiveColor: ColorValue;
  boxActiveBgColor: ColorValue;
  boxDeactiveBgColor: ColorValue;
  textColor: ColorValue;
  box: boolean;
  renderIcon: any;
}

interface StateInterface {
  activeIndex: number;
  fadeAnim: Animated.Value;
  animations: any[];
}

class RadioButtonRN extends React.Component<PropsInterface, StateInterface> {
  animations: any[];
  static defaultProps = {
    style: {},
    boxStyle: {},
    textStyle: {},
    initial: -1,
    circleSize: 18,
    duration: 500,
    data: [],
    animationTypes: [],
    selectedBtn: () => {},
    activeColor: "#fff",
    deactiveColor: "#e2e2e2",
    boxActiveBgColor: "#00000000",
    boxDeactiveBgColor: "#00000000",
    textColor: "#fff",
    box: true,
  };
  constructor(props: PropsInterface) {
    super(props);

    this.state = {
      activeIndex: -1,
      fadeAnim: new Animated.Value(0),
      animations: [],
    };
    // this.fadeAnim = new Animated.Value(0);

    this.animations = [
      {
        name: "zoomIn",
        animation: {
          scale: this.state.fadeAnim.interpolate({
            inputRange: [0, 1],
            outputRange: [0, 1],
          }),
        },
      },
      {
        name: "pulse",
        animation: {
          scale: this.state.fadeAnim.interpolate({
            inputRange: [0, 0.4, 0.7, 1],
            outputRange: [0.7, 1, 1.3, 1],
          }),
        },
      },
      {
        name: "shake",
        animation: {
          scale: this.state.fadeAnim.interpolate({
            inputRange: [0, 0.2, 0.4, 0.6, 0.8, 1],
            outputRange: [0.8, 1.2, 0.8, 1.2, 0.8, 1],
          }),
        },
      },
      {
        name: "rotate",
        animation: {
          rotate: this.state.fadeAnim.interpolate({
            inputRange: [0, 1],
            outputRange: ["0deg", "360deg"],
          }),
        },
      },
    ];

    this._changeRadio = this._changeRadio.bind(this);
    this._checkAnimatons = this._checkAnimatons.bind(this);
  }

  componentDidMount() {
    this._checkAnimatons();
    this.fadeInAnimation();
  }

  componentDidUpdate(prevProps: PropsInterface) {
    if (this.state.activeIndex === -1 && this.props.initial > 0) {
      const initialActive = this.props.initial - 1;
      this._changeRadio(this.props.data[initialActive], initialActive);
    }
    if (this.props.initial !== prevProps.initial) {
      const initialActive = this.props.initial - 1;
      this._changeRadio(this.props.data[initialActive], initialActive);
    }
    if (this.props.animationTypes !== prevProps.animationTypes) {
      this._checkAnimatons();
    }
  }

  _checkAnimatons() {
    const { animationTypes } = this.props;

    this.setState({ animations: [] });
    const newAnim: any[] = [];
    animationTypes &&
      animationTypes.map((item) => {
        const itm = this.animations.find((e) => e.name === item);
        if (itm) {
          newAnim.push(itm.animation);
        }
      });
    this.setState({ animations: newAnim });
  }

  _changeRadio(item: IAudioMode, activeIndex: number) {
    this.setState({ activeIndex });
    if (activeIndex !== this.state.activeIndex) {
      this.fadeInAnimation();
    }
    this.props.selectedBtn(item);
  }

  fadeInAnimation = () => {
    Animated.timing(this.state.fadeAnim, {
      toValue: 0,
      duration: 0,
      useNativeDriver: true,
    }).start(() => {
      Animated.timing(this.state.fadeAnim, {
        toValue: 1,
        duration: this.props.duration,
        delay: 10,
        useNativeDriver: true,
      }).start();
    });
  };

  render() {
    // let { activeIndex, fadeAnim, animations } = this.state;
    const {
      boxStyle,
      style,
      // circleSize,
      textStyle,
      data,
      // icon,
      activeColor,
      deactiveColor,
      boxActiveBgColor,
      boxDeactiveBgColor,
      box,
      textColor,
    } = this.props;

    return (
      <View style={style}>
        {data.map((item, index) => {
          return (
            <TouchableOpacity
              key={index}
              style={[
                box ? styles.productBox : styles.productBoxLess,
                box && {
                  backgroundColor: item.selected ? boxActiveBgColor : boxDeactiveBgColor,
                  borderColor: item.selected ? activeColor : deactiveColor,
                },
                boxStyle,
                { borderWidth: item.selected ? 1 : 0 },
              ]}
              activeOpacity={0.9}
              onPress={() => this._changeRadio(item, index)}
            >
              <View style={styles.leftProductBox}>{this.props.renderIcon(item.type)}</View>

              <View style={[styles.centerProductBox]}>
                <Text
                  style={[
                    {
                      color: textColor,
                    },
                    textStyle,
                  ]}
                >
                  {item.type === AUDIO_MODE_TYPE.BLUETOOTH && item.name ? item.name : item.type}
                </Text>
              </View>
            </TouchableOpacity>
          );
        })}
      </View>
    );
  }
}

const styles = StyleSheet.create({
  productBox: {
    flexDirection: "row",
    borderRadius: 7,
    borderWidth: 1,
    paddingHorizontal: 10,
    paddingVertical: 15,
    marginTop: 10,
  },
  productBoxLess: {
    flexDirection: "row",
    marginTop: 10,
  },
  leftProductBox: {
    flex: 1,
    alignItems: "center",
    justifyContent: "center",
  },
  centerProductBox: {
    flex: 6,
    justifyContent: "flex-start",
    alignItems: "center",
    paddingHorizontal: 4,
    flexDirection: "row",
  },
  circle: {
    borderWidth: 1,
    borderRadius: 10000,
    alignItems: "center",
    justifyContent: "center",
  },
  icon: {
    borderWidth: 1,
    borderRadius: 10000,
    alignItems: "center",
    justifyContent: "center",
  },
  circleFill: {
    borderWidth: 1,
    borderRadius: 10000,
  },
});

export default RadioButtonRN;
